    aomDialogTitle: 'Rahan ikä',
    aomDialogBody: 'Rahan ikä kertoo, kuinka kauan keskimäärin viimeisten 30 päivän aikana käyttämäsi raha oli tileilläsi ennen käyttöä.\n\nSuurempi luku tarkoittaa, että käytät rahaa, jonka olet ansainnut jo aiemmin — merkki terveestä taloudellisesta puskurista. Pienempi luku tarkoittaa, että käytät rahaa pian sen saapumisen jälkeen.\n\nLaskenta toistaa tapahtumahistorian FIFO-jonona: jokainen tulo merkitään saapumispäivällään, ja kun käytät rahaa, vanhin raha kuluu ensin. Näytetty arvo on viimeisten 30 päivän aikana käytetyn rahan keski-ikä päivinä.\n\nKäyttötiliesi väliset siirrot ja oikaisut on jätetty pois — ne vain siirtelevät rahaa. Säästöihin, sijoituksiin tai lainan lyhennykseen siirretty raha kuluttaa ensin vanhimmat rahasi kuten menot, mutta sitä ei lasketa kulutukseksi. Takaisin käyttötileille siirretty raha lasketaan uudeksi tuloksi.',
