    howToFixEnvelopeRefs: 'Nämä tapahtumat viittaavat kirjekuoreen, jota ei enää ole. Avaa kukin tapahtuma ja valitse olemassa oleva kirjekuori tai luo puuttuva kirjekuori uudelleen.',
