    howToFixDuplicateKeys: 'Useampi tapahtuma väittää maksavansa saman ajastetun laskun, joten yksi erä lasketaan monta kertaa. Avaa ne, säilytä se joka todella maksoi laskun ja poista loput.',
    howToFixStaleKeys: 'Näiden tapahtumien päivämäärä on kaukana siitä aikataulutetusta laskusta, jonka ne väittävät maksavansa. Aikataulutetun rivin päivän muuttaminen siirtää päivää mutta jättää alkuperäisen linkin, joten ennuste laskee todella maksetun laskun toiseen kertaan — ilman näkyvää syytä. Avaa kukin ja joko siirrä päivä takaisin tai poista rivi ja anna aikataulun luoda oikea erä.',
    howToFixDates: 'Näistä puuttuu päivä tai se ei ole muodossa VVVV-KK-PP, joten tapahtumat järjestyvät ja kirjautuvat väärään kuukauteen ilman virheilmoitusta. Avaa kukin ja aseta oikea päivä.',
    howToFixSelfTransfers: 'Nämä siirrot alkavat ja päättyvät samaan paikkaan, joten ne eivät siirrä mitään mutta näkyvät silti tapahtumina. Avaa kukin ja korjaa toinen pää, tai poista tapahtuma.',
    howToFixDuplicateIds: 'Kahdella tai useammalla tapahtumalla on sama tunnus, joten vain yksi niistä on tavoitettavissa ja se vastaa kaikkien puolesta. Yleensä tuonnin jäljiltä. Poista kaksoiskappaleet ja kirjaa ne tarvittaessa uudelleen.',
    howToFixCoercions: 'Tämän rivin summa ei ole äärellinen luku — Infinity, NaN tai tekstiä, jota moottori ei osaa lukea. Jokainen rahalaskenta muuntaa sen nollaksi sen sijaan, että näkymä kaatuisi, joten rivi ei hiljaisesti vaikuta mihinkään. Avaa se ja syötä summa uudelleen.',
    howToFixConservation: 'Tämä tapahtuma siirtää tileillä eri summan kuin kirjekuorissa. Molemmat puolet kuvaavat samaa rahaa, joten toinen niistä on väärin — yleensä summa on muutettu vain toiselle puolelle tai jakoriveiltä puuttuu osa kokonaissummasta. Avaa tapahtuma ja syötä summa uudelleen.',
    howToFixUnknownTypes: 'Näiden tapahtumien tyyppiä sovellus ei tunne — yleensä kirjoitusvirhe tuonnissa tai käsin muokatussa tiedostossa — joten ne eivät siirrä rahaa missään saldossa, vaikka näkyvät tapahtumina. Avaa kukin ja valitse sen oikea tyyppi kohdasta "Korjaa tyypiksi"; lomake tallentaa sen sitten sillä tyypillä.',
    howToFixItemLinks: 'Nämä tapahtumat on linkitetty budjettiriviin, joka kuuluu nyt toiseen kirjekuoreen, joten täyttöaste ohittaa linkin ja laskee kulun linkittämättömäksi. Avaa kukin ja valitse budjettirivi uudelleen tai aseta se automaattiseksi.',
